INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Trends > Technologische Entwicklungstrends von IT-Systemen feststellen sowie ihre wirtschaftlichen, sozialen sowie beruflichen Auswirkungen aufzeigen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können technologische Entwicklungstrends von IT-Systemen ausschließlich wirtschaftliche Auswirkungen haben?', 2, '[{"text": "Nein", "correct": true, "because": "Sie beeinflussen auch soziale und berufliche Bereiche"}, {"text": "Ja", "correct": false, "because": "Auswirkungen sind vielschichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Feststellung technologischer Entwicklungstrends von IT-Systemen ohne Berücksichtigung sozialer Auswirkungen vollständig?', 2, '[{"text": "Nein", "correct": true, "because": "Soziale Aspekte sind integraler Bestandteil"}, {"text": "Ja", "correct": false, "because": "Soziale Auswirkungen sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Haben technologische Entwicklungstrends von IT-Systemen immer positive berufliche Auswirkungen?', 2, '[{"text": "Nein", "correct": true, "because": "Sie können auch Arbeitsplätze gefährden"}, {"text": "Ja", "correct": false, "because": "Negative Effekte sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen technologische Entwicklungstrends von IT-Systemen zwingend neue Hardware erfordern?', 2, '[{"text": "Nein", "correct": true, "because": "Softwaretrends können unabhängig sein"}, {"text": "Ja", "correct": false, "because": "Trends können softwarebasiert sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Können technologische Entwicklungstrends von IT-Systemen die Gesellschaft isolieren?', 2, '[{"text": "Ja", "correct": true, "because": "Digital Divide kann soziale Kluften verstärken"}, {"text": "Nein", "correct": false, "because": "Isolation ist eine mögliche Folge"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche wirtschaftliche Auswirkung haben technologische Entwicklungstrends von IT-Systemen am häufigsten?', 2, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Automatisierung reduziert Kosten"}, {"text": "Marktsättigung", "correct": false, "because": "Sekundäre Folge"}, {"text": "Preisstabilität", "correct": false, "because": "Weniger direkt beeinflusst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche soziale Auswirkung wird oft durch technologische Entwicklungstrends von IT-Systemen verstärkt?', 3, '[{"text": "Digitale Kluft", "correct": true, "because": "Ungleichheit im Zugang wächst"}, {"text": "Kulturelle Homogenität", "correct": false, "because": "Nicht primär"}, {"text": "Physische Mobilität", "correct": false, "because": "Kaum betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher berufliche Bereich wird durch technologische Entwicklungstrends von IT-Systemen am stärksten beeinflusst?', 2, '[{"text": "IT-Fachkräfte", "correct": true, "because": "Direkte Anpassung erforderlich"}, {"text": "Verwaltung", "correct": false, "because": "Indirekter Einfluss"}, {"text": "Produktion", "correct": false, "because": "Weniger spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Trend beeinflusst die wirtschaftlichen Auswirkungen von IT-Systemen am meisten?', 2, '[{"text": "Künstliche Intelligenz", "correct": true, "because": "Breite Anwendung und Effizienz"}, {"text": "Blockchain", "correct": false, "because": "Spezifischer Einsatz"}, {"text": "Augmented Reality", "correct": false, "because": "Nischenanwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist am effektivsten, um technologische Entwicklungstrends von IT-Systemen festzustellen?', 2, '[{"text": "Marktanalysen", "correct": true, "because": "Zeigen aktuelle Entwicklungen"}, {"text": "Kundenbefragungen", "correct": false, "because": "Subjektiv und verzögert"}, {"text": "Interne Audits", "correct": false, "because": "Begrenzt auf Unternehmen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche wirtschaftlichen Auswirkungen haben technologische Entwicklungstrends von IT-Systemen?', 4, '[{"text": "Kostensenkung", "correct": true, "because": "Automatisierung spart Ressourcen"}, {"text": "Umsatzsteigerung", "correct": true, "because": "Neue Märkte entstehen"}, {"text": "Wettbewerbsvorteil", "correct": true, "because": "Innovation hebt ab"}, {"text": "Arbeitszeitverlängerung", "correct": false, "because": "Eher Verkürzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche sozialen Auswirkungen können technologische Entwicklungstrends von IT-Systemen haben?', 3, '[{"text": "Verbesserte Kommunikation", "correct": true, "because": "Vernetzung steigt"}, {"text": "Soziale Isolation", "correct": true, "because": "Digitaler Fokus kann trennen"}, {"text": "Bildungszugang", "correct": true, "because": "Online-Lernen wächst"}, {"text": "Physische Gesundheit", "correct": false, "because": "Indirekt betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche beruflichen Auswirkungen ergeben sich aus technologischen Entwicklungstrends von IT-Systemen?', 4, '[{"text": "Neue Berufsfelder", "correct": true, "because": "Technologien schaffen Jobs"}, {"text": "Automatisierung von Aufgaben", "correct": true, "because": "Routine wird ersetzt"}, {"text": "Qualifikationsanforderungen", "correct": true, "because": "Spezialisierung nötig"}, {"text": "Lohnsenkung", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien prägen aktuelle Entwicklungstrends von IT-Systemen?', 3, '[{"text": "Künstliche Intelligenz", "correct": true, "because": "Breite Anwendung"}, {"text": "Cloud Computing", "correct": true, "because": "Skalierbarkeit"}, {"text": "Internet der Dinge", "correct": true, "because": "Vernetzung steigt"}, {"text": "Manuelle Datenverarbeitung", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, technologische Entwicklungstrends von IT-Systemen zu analysieren?', 3, '[{"text": "Fachmessen", "correct": true, "because": "Zeigen Innovationen"}, {"text": "Trendberichte", "correct": true, "because": "Bieten Prognosen"}, {"text": "Wettbewerbsanalysen", "correct": true, "because": "Vergleichen Markt"}, {"text": "Mitarbeiterbefragungen", "correct": false, "because": "Zu subjektiv"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Technologische Entwicklungstrends von IT-Systemen fördern wirtschaftliches Wachstum. b) Sie haben keine sozialen Auswirkungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wachstum ja, soziale Effekte auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Technologische Entwicklungstrends schaffen neue Berufe. b) Sie eliminieren keine Arbeitsplätze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Neue Jobs ja, alte weg auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Trends wie KI erhöhen die Effizienz. b) Soziale Auswirkungen sind immer positiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, sozial gemischt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Technologische Trends erfordern neue Qualifikationen. b) Wirtschaftliche Auswirkungen sind immer negativ.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualifikationen ja, negativ nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Trends wie Cloud Computing fördern Skalierbarkeit. b) Berufliche Auswirkungen sind unerheblich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skalierbarkeit ja, beruflich relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

